import java.util.*

fun main() {
    val A = readLine()!!.toLong()
    if (A == 1L) {
        println(1)
        return
    }

    // Factorize A into primes
    val factors = factorize(A)
    val divisors = generateDivisors(factors)

    // For each divisor d of A, check if it can be written as (p^(e+1)-1)/(p-1) for some prime p and e >=1
    val validDivisors = mutableListOf<Long>()
    for (d in divisors) {
        if (d == 1L) continue
        val p = findPrimeForSum(d)
        if (p != null) {
            validDivisors.add(d)
        }
    }

    // Now, we need to find the number of subsets of validDivisors that multiply to A, with pairwise coprime elements
    // Use DP approach
    val dp = HashMap<Long, Int>()
    dp[1L] = 1

    for (d in validDivisors) {
        val newDp = HashMap<Long, Int>()
        for ((prod, count) in dp) {
            if (prod > A / d) continue
            val newProd = prod * d
            if (newProd > A) continue
            newDp[newProd] = newDp.getOrDefault(newProd, 0) + count
        }
        for ((k, v) in newDp) {
            dp[k] = dp.getOrDefault(k, 0) + v
        }
    }

    println(dp[A] ?: 0)
}

fun factorize(n: Long): List<Pair<Long, Int>> {
    val factors = mutableListOf<Pair<Long, Int>>()
    var num = n
    var i = 2L
    while (i * i <= num) {
        if (num % i == 0) {
            var count = 0
            while (num % i == 0) {
                num /= i
                count++
            }
            factors.add(Pair(i, count))
        }
        i++
    }
    if (num > 1) {
        factors.add(Pair(num, 1))
    }
    return factors
}

fun generateDivisors(factors: List<Pair<Long, Int>>): List<Long> {
    val divisors = mutableListOf<Long>()
    divisors.add(1L)
    for ((p, exp) in factors) {
        val temp = mutableListOf<Long>()
        for (d in divisors) {
            var current = d
            for (e in 0..exp) {
                temp.add(current)
                current *= p
            }
        }
        divisors.clear()
        divisors.addAll(temp)
    }
    return divisors.sorted()
