fun findPrimeForSum(d: Long): Long? {
    // Check if d can be written as (p^(e+1) - 1)/(p - 1) for some prime p and e >=1
    // Try e from 1 to log2(d)
    for (e in 1..60) {
        val p = findPForE(d, e)
        if (p != null && isPrime(p)) {
            return p
        }
    }
    return null
}

fun findPForE(d: Long, e: Int): Long? {
    // Solve (p^(e+1) - 1)/(p - 1) = d
    // For e=1: p + 1 = d => p = d-1
    // For e=2: p^2 + p + 1 = d => solve quadratic
    // For higher e, use binary search
    if (e == 1) {
        val p = d - 1
        if (p >= 2) return p
        return null
    } else if (e == 2) {
        val discriminant = 4 * d - 3
        if (discriminant < 0) return null
        val sqrtDisc = sqrt(discriminant.toDouble()).toLong()
        if (sqrtDisc * sqrtDisc != discriminant) return null
        val p = (-1 + sqrtDisc) / 2
        if (p >= 2 && (p * p + p + 1 == d)) return p
        return null
    } else {
        // Binary search for p in (p^(e+1) - 1)/(p - 1) = d
        var low = 2L
        var high = d
        while (low <= high) {
            val mid = (low + high) / 2
            val sum = geometricSum(mid, e)
            if (sum == d) return mid
            if (sum < d) {
                low = mid + 1
            } else {
                high = mid - 1
            }
        }
        return null
    }
}

fun geometricSum(p: Long, e: Int): Long {
    // Compute 1 + p + p^2 + ... + p^e
    var sum = 1L
    var term = 1L
    for (i in 1..e) {
        term *= p
        sum += term
        if (sum > 1e18) return Long.MAX_VALUE
    }
    return sum
}

fun isPrime(n: Long): Boolean {
    if (n < 2) return false
    if (n == 2L) return true
    if (n % 2 == 0) return false
    var i = 3L
    while (i * i <= n) {
        if (n % i == 0) return false
        i += 2
    }
    return true
}
