fun countSolutions(
    remaining: Long,
    divisors: List<Long>,
    index: Int,
    memo: HashMap<Pair<Long, Int>, Long>
): Long {
    if (remaining == 1L) return 1L
    if (index >= divisors.size) return 0L
    val key = Pair(remaining, index)
    if (memo.containsKey(key)) return memo[key]!!
    var count = 0L
    for (i in index until divisors.size) {
        val d = divisors[i]
        if (d > remaining) break
        if (remaining % d != 0L) continue
        val (p, k) = findPrimeAndExponent(d)
        if (p == 0) continue
        count += countSolutions(remaining / d, divisors, i + 1, memo)
    }
    memo[key] = count
    return count
}

fun findPrimeAndExponent(d: Long): Pair<Int, Int> {
    if (d < 2) return Pair(0, 0)
    for (k in 1..40) {
        val p = findPrimeForSum(d, k)
        if (p != 0) return Pair(p, k)
    }
    return Pair(0, 0)
}

fun findPrimeForSum(d: Long, k: Int): Int {
    val numerator = d * (2 - 1) + 1
    if (k == 1) {
        if (d >= 2) return d.toInt()
        return 0
    }
    val p = (d - 1).toDouble().pow(1.0 / k).toInt()
    for (candidate in p - 2..p + 2) {
        if (candidate < 2) continue
        var sum = 0L
        var term = 1L
        for (i in 0..k) {
            sum += term
            term *= candidate
        }
        if (sum == d) return candidate
    }
    return 0
}

fun primeFactors(n: Long): Map<Long, Int> {
    val factors = HashMap<Long, Int>()
    var num = n
    while (num % 2 == 0L) {
        factors[2] = factors.getOrDefault(2, 0) + 1
        num /= 2
    }
    var i = 3L
    while (i * i <= num) {
        while (num % i == 0L) {
            factors[i] = factors.getOrDefault(i, 0) + 1
            num /= i
        }
        i += 2
    }
    if (num > 1) factors[num] = 1
    return factors
}

fun generateDivisors(factors: Map<Long, Int>): List<Long> {
    val divisors = mutableListOf<Long>()
    divisors.add(1L)
    for ((p, exp) in factors) {
        val currentSize = divisors.size
        for (e in 1..exp) {
            val pe = p.toDouble().pow(e).toLong()
            for (i in 0 until currentSize) {
                divisors.add(divisors[i] * pe)
            }
        }
    }
    divisors.sort()
    return divisors
}
