    return divisors.toList()
}

fun sumOfDivisors(x: Long): Long {
    var sum = 0L
    val sqrtX = Math.sqrt(x.toDouble()).toLong()
    for (i in 1..sqrtX) {
        if (x % i == 0L) {
            sum += i
            if (i != x / i) {
                sum += x / i
            }
        }
    }
    return sum
}
